<?php require_once __DIR__.'/functions.php';layout_header('Dashboard');$s=stats(load_db());$cards=['Total Words'=>$s['total'],'Total HSK1'=>$s['levels'][1],'Total HSK2'=>$s['levels'][2],'Total HSK3'=>$s['levels'][3],'Total HSK4'=>$s['levels'][4],'Total HSK5'=>$s['levels'][5],'Extra Words'=>$s['Extra'],'Missing Bangla'=>$s['missing_bangla'],'Missing Bangla Pronunciation'=>$s['missing_bp'],'Missing Audio'=>$s['missing_audio'],'Missing Examples'=>$s['missing_examples'],'Recently Updated'=>count($s['recent'])];?><div class="row g-3"><?php foreach($cards as $k=>$v):?><div class="col-6 col-md-4 col-xl-2"><div class="stat-card"><span><?=h($k)?></span><strong><?=h($v)?></strong></div></div><?php endforeach;?></div><div class="row g-3 mt-2"><div class="col-lg-6"><div class="panel"><h2>Words per level</h2><canvas id="levelChart" data-values='<?=h(json_encode(array_values($s['levels'])))?>'></canvas></div></div><div class="col-lg-6"><div class="panel"><h2>Recently Updated</h2><div class="list-group"><?php foreach($s['recent'] as $w):?><a class="list-group-item" href="words.php?q=<?=urlencode((string)$w['id'])?>"><b><?=h($w['hanzi']??'')?></b> <?=h($w['pinyin']??'')?> <span class="badge bg-secondary">HSK <?=h($w['level']??'Extra')?></span></a><?php endforeach;?></div></div></div></div><?php layout_footer();?>